int epic_ingress(ctx, rank, frame, len):
  if (!wire_validate(frame,len,D,&w)) { ctx->wire_bad++; return 0; }
  if (!endpoint_ok(rank, frame, w.qpn)) { ctx->ep_bad++; return 0; }
  if (w.is_ack) {
     ctx->ack_ok++;
     uint32_t n = (w.psn - ctx->start + 1) & 0xffffff;
     if (n > ctx->ack[rank] && n <= ctx->sent[rank]) ctx->ack[rank]=n; else ctx->ign++;
     service(ctx,-1);
  } else {
     uint32_t p = (w.psn - ctx->start) & 0xffffff;
     if (p >= ctx->K || (ctx->kind==BCAST && rank != ctx->root)) { ctx->ep_bad++; return 0; }
     ctx->data_ok++;
     uint32_t b = ctx->b;
     if (p < b) { ctx->stale++; ctx->repeat[rank]=1; service(ctx,-1); return 0; }
     uint32_t lim = b + ctx->N; if (lim > ctx->K) lim = ctx->K;
     if (p >= lim) { ctx->blocked++; service(ctx,-1); return 0; }
     unsigned i = p % ctx->N;
     if (!ctx->used[i]) { alloc slot i with p; }
     /* slot must hold p (identity) */
     if (ctx->slot_p[i] != p) { /* shouldn't happen: free and re-alloc */ }
     if (ctx->mask[i] & (1<<rank)) { ctx->dup++; ctx->repeat[rank]=1; service(ctx,-1); return 0;}
     accept payload; ctx->mask[i] |= bit; ctx->accepted++;
     advance R[rank];
     service(ctx,-1);
  }
  return 0;
```

